VALUES ('MOOD_IMPULSE_CONTROL', 'MOOD-03', 22, 'MOOD', 'อารมณ์และสุขภาพจิต', 'ใน 7 วันที่ผ่านมา ท่านรู้สึกมีความอยากทำบางสิ่งอย่างรุนแรงจนหยุดตัวเองได้ยาก เช่น เล่นการพนัน กินอาหารมากผิดปกติ ซื้อของมากผิดปกติ หรือมีความต้องการทางเพศเพิ่มขึ้นผิดปกติไหม?', NULL, 'single_choice_with_text', '[{"code": "no", "label": "ไม่มี", "score": null}, {"code": "yes", "label": "มี (ระบุว่าเป็นเรื่องอะไร)", "score": null}, {"code": "no_answer", "label": "ไม่ต้องการตอบ", "score": null}, {"code": "unknown", "label": "ไม่ทราบ (ผู้ดูแลไม่แน่ใจ)", "score": null}]'::jsonb, '{}'::jsonb, '{"rule": "มี / yes", "severity": "warning", "clinic_tag": "impulse_control"}'::jsonb, 'both', 'รองรับ voice-to-text + ให้ผู้ดูแลกรอกแทนได้', 'sensitive_optional', 'impulse_control_symptom', '1.6', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'Full/Pre-Visit', TRUE)
