VALUES ('AUTO_ORTHOSTATIC_SYMPTOM', 'AUT-01', 23, 'AUT', 'ระบบ Autonomic', 'วันนี้เมื่อท่านลุกขึ้นยืนจากท่านั่งหรือนอน รู้สึกเวียนหัว หน้ามืด เกือบเป็นลม หรือเป็นลมจริงไหม?', NULL, 'single_choice_with_count', '[{"code": "no", "label": "ไม่มี", "score": 0}, {"code": "mild_once", "label": "เวียนหัว/หน้ามืด 1 ครั้ง", "score": 1}, {"code": "mild_repeat", "label": "เวียนหัว/หน้ามืด หลายครั้ง", "score": 2}, {"code": "near_faint", "label": "เกือบเป็นลม", "score": 3}, {"code": "faint", "label": "เป็นลมจริง", "score": 4}]'::jsonb, '{}'::jsonb, '{"rule": "score >= 2 (เกิดซ้ำ)  OR  answer_code in [near_faint, faint]  OR  paired with MOT-05 fall/near-fall same day", "severity": "red", "clinic_tag": "orthostatic_symptom", "link": "MOT-05", "note": "ปรับจาก fire-ครั้งเดียว เพื่อลด alert fatigue"}'::jsonb, 'both', 'ใช้ stepper (+/-) ปุ่มใหญ่ ไม่ใช้คีย์บอร์ด', 'core', 'orthostatic_symptom_count', '1.12', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'MVP1', TRUE)
