VALUES ('AUTO_CONSTIPATION', 'AUT-02', 24, 'AUT', 'ระบบ Autonomic', 'ใน 7 วันที่ผ่านมา ท่านมีปัญหาขับถ่ายยากหรือถ่ายน้อยกว่าปกติ (น้อยกว่า 3 ครั้ง/สัปดาห์ หรือต้องเบ่งมาก) ไหม?', NULL, 'single_choice', '[{"code": "no", "label": "ไม่มี", "score": null}, {"code": "c1", "label": "มีบ้าง", "score": null}, {"code": "c2", "label": "มีมาก", "score": null}]'::jsonb, '{}'::jsonb, '{"rule": "มีมาก", "severity": "warning", "clinic_tag": "constipation"}'::jsonb, 'both', NULL, 'optional', 'constipation_level', '1.11', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'MVP2', TRUE)
