VALUES ('AUTO_URINARY_SYMPTOM', 'AUT-03', 25, 'AUT', 'ระบบ Autonomic', 'ใน 7 วันที่ผ่านมา ท่านมีปัญหาปัสสาวะบ่อยผิดปกติ ต้องรีบวิ่งไปห้องน้ำ หรือกลั้นไม่ค่อยได้ไหม?', NULL, 'ordinal_scale_0_4', '[{"code": "0", "label": "ไม่มีปัญหา", "score": 0}, {"code": "1", "label": "บ่อยขึ้นเล็กน้อย", "score": 1}, {"code": "2", "label": "ต้องรีบแต่ยังไปทัน", "score": 2}, {"code": "3", "label": "กลั้นไม่ค่อยได้ บางครั้งไม่ทัน", "score": 3}, {"code": "4", "label": "กลั้นไม่ได้เลย", "score": 4}]'::jsonb, '{}'::jsonb, '{"rule": "score >= 3", "severity": "warning", "clinic_tag": "urinary_urgency"}'::jsonb, 'both', NULL, 'optional', 'urinary_score', '1.10', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'MVP2', TRUE)
