VALUES ('ADL_SWALLOWING', 'ADL-05', 31, 'ADL', 'การดูแลตัวเอง (ADL)', 'ใน 7 วันที่ผ่านมา ท่านรู้สึกว่ากลืนอาหาร น้ำ หรือยาลำบาก หรือสำลักบ้างไหม?', NULL, 'ordinal_scale_0_4', '[{"code": "0", "label": "กลืนได้ปกติ", "score": 0}, {"code": "1", "label": "ช้าลงหรือต้องระวัง แต่ไม่สำลัก", "score": 1}, {"code": "2", "label": "สำลักบางครั้ง", "score": 2}, {"code": "3", "label": "สำลักบ่อย ต้องปรับอาหาร", "score": 3}, {"code": "4", "label": "กลืนไม่ได้ ต้องใส่สาย", "score": 4}]'::jsonb, '{}'::jsonb, '{"rule": "score >= 2", "severity": "red", "clinic_tag": "swallowing_choking"}'::jsonb, 'both', NULL, 'optional', 'swallowing_score', '2.3', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'MVP2', TRUE)
