VALUES ('MOOD_APATHY', 'MOOD-01b', NULL, 'MOOD', 'อารมณ์และสุขภาพจิต', 'วันนี้ท่านรู้สึกเฉยๆ ไม่อยากทำอะไร หรือขาดแรงจูงใจที่จะทำสิ่งที่เคยทำ (โดยไม่จำเป็นต้องรู้สึกเศร้า) ไหม?', NULL, 'ordinal_scale_0_4', '[{"code": "0", "label": "ไม่รู้สึกเลย", "score": 0}, {"code": "1", "label": "รู้สึกนิดหน่อย ไม่รบกวน", "score": 1}, {"code": "2", "label": "รู้สึกชัดเจน แต่ยังทำสิ่งต่างๆ ได้", "score": 2}, {"code": "3", "label": "รู้สึกมากจนกระทบชีวิต", "score": 3}, {"code": "4", "label": "รู้สึกหนักมากจนทำอะไรไม่ได้", "score": 4}]'::jsonb, '{}'::jsonb, '{"rule": "score >= 3", "severity": "warning", "clinic_tag": "apathy_high"}'::jsonb, 'both', NULL, 'core', 'apathy_score', '1.5', 'แต่งขึ้นเอง ได้แรงบันดาลใจจาก MDS-UPDRS (รอ compliance ยืนยัน)', NULL, 'MVP1', TRUE)
