VALUES ('MOOD_SUICIDAL_IDEATION', 'MOOD-04', NULL, 'MOOD', 'อารมณ์และสุขภาพจิต', 'ใน 7 วันที่ผ่านมา ท่านเคยมีความคิดว่าอยากทำร้ายตัวเอง หรือรู้สึกว่าไม่อยากมีชีวิตอยู่บ้างไหม?', NULL, 'single_choice_safety', '[{"code": "none", "label": "ไม่เคย", "score": 0}, {"code": "sometimes", "label": "มีบ้างเป็นบางครั้ง", "score": 1}, {"code": "often", "label": "มีบ่อย", "score": 2}, {"code": "plan", "label": "มี และเคยคิดวางแผน", "score": 3}, {"code": "no_answer", "label": "ไม่ต้องการตอบ", "score": null}]'::jsonb, '{}'::jsonb, '{"rule": "answer_code != none  (รวม no_answer = fail-safe)", "severity": "urgent", "clinic_tag": "suicidal_ideation", "in_app_action": "แสดง crisis resource ทันที (สายด่วนสุขภาพจิต 1323) + disclaimer ว่าแอปไม่ใช่บริการฉุกเฉิน", "respondent": "patient_only — ถ้ามีแต่ caregiver ให้แสดง resource และไม่บันทึกเป็น screen ผู้ป่วย"}'::jsonb, 'patient_only', NULL, 'sensitive_core', 'suicidal_ideation', 'PHQ-9 item9 (construct)', 'construct จาก PHQ-9 item 9 — ต้องยืนยัน licensing PHQ-9', NULL, 'MVP1', TRUE)
